return array(
	'name' => 'Romanian',
	'register' => 'Formal dumneavoastră in every string and slot, meta, alt, aria and JSON-LD included: second-person plural verbs and plural predicative adjectives („Sunteți pregătiți…?”, never „Nu sunteți sigur”), the possessive „dumneavoastră” in full, never „dvs.”, never a tu form. Buttons and link labels keep the English verb as a polite plural imperative („Browse catalog” = „Consultați catalogul”, „Download” = „Descărcați”, „Contact us” = „Contactați-ne”), never a bare noun, and carry no pronoun or possessive („Protecția investiției”, not „Protejați-vă investiția”).',
	'b2b_terminology' => array(
